-- ============================================
-- FIX — cours Vecteurs aligné sur le vrai cahier (chapitre 6)
-- A coller dans : Supabase > SQL Editor > New query
-- ============================================
-- D'apres le cahier de cours reel d'Anais (chapitre 6, "Vecteurs et
-- repere"), le determinant et la colinearite font partie du meme
-- chapitre que les coordonnees/la norme/le milieu, et la page
-- "Preparer le controle" du cahier les inclut dans son QCM de revision.
-- Le cours avait ete ecrit avant d'avoir ce cahier sous les yeux et les
-- renvoyait a plus tard : corrige ici, avec en plus la base orthonormee
-- et le repere (O ; i, j), absents du premier jet.

UPDATE cours
SET contenu = $coursJson4$[{"id": 1, "type": "texte", "content": "Un vecteur est un déplacement. $\\overrightarrow{AB}$, c'est aller de A à B. Trois informations : direction, sens, longueur. Vérifié contre le cahier de cours (chapitre 6, « Vecteurs et repère ») : ce chapitre suppose connus l'égalité de deux vecteurs, la translation et la relation de Chasles, vues au chapitre précédent."}, {"id": 2, "type": "definition", "content": "Deux vecteurs sont égaux s'ils ont la même direction, le même sens et la même longueur — peu importe où on les dessine.", "titre": "Deux vecteurs égaux"}, {"id": 3, "type": "definition", "content": "Translation de vecteur u : chaque point glisse de la même flèche. L'image de A est A' tel que $\\overrightarrow{AA'}$ = $\\vec{u}$. La figure ne change ni de forme ni de taille.", "titre": "Translation"}, {"id": 4, "type": "theoreme", "content": "ABCD est un parallélogramme si et seulement si $\\overrightarrow{AB}$ = $\\overrightarrow{DC}$. On lit les lettres dans l'ordre du tour.", "titre": "Parallélogramme"}, {"id": 5, "type": "theoreme", "content": "$\\overrightarrow{AB}$ + $\\overrightarrow{BC}$ = $\\overrightarrow{AC}$. On enchaîne les flèches, la lettre du milieu disparaît.", "titre": "Relation de Chasles"}, {"id": 6, "type": "definition", "content": "Deux vecteurs i et j forment une base orthonormée s'ils ont la même longueur et des directions perpendiculaires. Tout vecteur $\\vec{w}$ se décompose de façon unique en $\\vec{w}$ = x·i + y·j : (x ; y) sont ses coordonnées dans cette base. Avec un point O, le triplet (O ; i, j) est un repère orthonormé du plan. C'est le cadre dans lequel on travaille pour tout ce qui suit.", "titre": "Base et repère"}, {"id": 7, "type": "definition", "content": "$\\overrightarrow{AB}$ a pour coordonnées (x_B − x_A ; y_B − y_A). Toujours arrivée moins départ. Deux vecteurs sont égaux si et seulement si ils ont les mêmes coordonnées.", "titre": "Coordonnées d'un vecteur"}, {"id": 8, "type": "methode", "content": "Avec u(x ; y) et v(x′ ; y′) :\nu + v a pour coordonnées (x + x′ ; y + y′)\nu − v a pour coordonnées (x − x′ ; y − y′)\nk·u (k réel) a pour coordonnées (kx ; ky)", "titre": "Opérations sur les coordonnées"}, {"id": 9, "type": "definition", "content": "La norme de $\\overrightarrow{AB}$, notée ‖$\\overrightarrow{AB}$‖, vaut $\\sqrt{x^2+y^2}$ où (x ; y) sont les coordonnées de $\\overrightarrow{AB}$. C'est aussi la distance AB.", "titre": "Norme"}, {"id": 10, "type": "definition", "content": "Les coordonnées du milieu d'un segment sont les moyennes de celles des deux extrémités.", "titre": "Milieu"}, {"id": 11, "type": "definition", "content": "Le déterminant de u(x ; y) et v(x′ ; y′) est det(u, v) = xy′ − x′y. Deux vecteurs sont colinéaires si et seulement si leur déterminant est nul. C'est ce qui sert à démontrer que deux droites sont parallèles, ou que des points sont alignés — c'est au programme de ce chapitre et donc du contrôle, pas une notion à part.", "titre": "Déterminant et colinéarité"}, {"id": 12, "type": "exemple", "content": "A(1 ; 2) et B(4 ; 6). $\\overrightarrow{AB}$ (4 − 1 ; 6 − 2) = (3 ; 4). Norme : √(3² + 4²) = √25 = 5. Milieu de [AB] : ((1+4)/2 ; (2+6)/2) = (2,5 ; 4).", "titre": "Exemple résolu"}, {"id": 13, "type": "exemple", "content": "A(−2 ; −1), B(2 ; −3), C(−4 ; 4), D(6 ; −1). $\\overrightarrow{AB}$ (4 ; −2) et $\\overrightarrow{CD}$ (10 ; −5). det($\\overrightarrow{AB}$, $\\overrightarrow{CD}$) = 4 × (−5) − 10 × (−2) = −20 + 20 = 0. $\\overrightarrow{AB}$ et $\\overrightarrow{CD}$ sont colinéaires, donc (AB) et (CD) sont parallèles.", "titre": "Utiliser la colinéarité"}, {"id": 14, "type": "remarque", "content": "Lire les lettres dans le mauvais ordre : pour ABCD, c'est $\\overrightarrow{AB}$ = $\\overrightarrow{DC}$, pas $\\overrightarrow{AB}$ = $\\overrightarrow{CD}$.\nFaire départ moins arrivée au lieu d'arrivée moins départ : la coordonnée change de signe.\nOublier les parenthèses avec un négatif : 5 − (−2) = 7, pas 3.\nConfondre colinéaire et égal : deux vecteurs colinéaires ont la même direction, mais pas forcément le même sens ni la même longueur.", "titre": "Pièges classiques"}, {"id": 15, "type": "remarque", "content": "La flèche se note toujours au-dessus des lettres : $\\overrightarrow{AB}$, jamais AB tout court. C'est sanctionné si elle manque. D'après le cahier, le contrôle porte sur tout le chapitre : coordonnées, norme, milieu, et déterminant/colinéarité — pas seulement l'égalité de deux vecteurs.", "titre": "Pour le contrôle"}]$coursJson4$
WHERE niveau = '2nde' AND chapitre = 'Vecteurs dans le plan';
